#!/usr/bin/env python3
"""Generate dot_neon_arm64.s / l2_neon_arm64.s (Weaviate float32 Dot / L2 NEON kernels).
Same staged design as gen_float_amd64.py: W=4 lanes, 8 chains, 32 elements per
main-loop trip; short paths for 4 <= len < 32 use as many chains as blocks."""

import sys

HEADER = """//go:build arm64

#include "textflag.h"

// Code generated by gen_float_arm64.py in this directory; DO NOT EDIT.
// Regenerate with: python3 gen_float_arm64.py .

// tailmask4 is 4 zero lanes followed by 4 all-ones lanes. Loading 4 lanes at
// byte offset r*4 (r = 1..3) yields a mask that keeps the last r lanes.
DATA tailmask4<>+0(SB)/4, $0x00000000
DATA tailmask4<>+4(SB)/4, $0x00000000
DATA tailmask4<>+8(SB)/4, $0x00000000
DATA tailmask4<>+12(SB)/4, $0x00000000
DATA tailmask4<>+16(SB)/4, $0xFFFFFFFF
DATA tailmask4<>+20(SB)/4, $0xFFFFFFFF
DATA tailmask4<>+24(SB)/4, $0xFFFFFFFF
DATA tailmask4<>+28(SB)/4, $0xFFFFFFFF
GLOBL tailmask4<>(SB), RODATA|NOPTR, $32
"""

W, C = 4, 8
TRIP = W * C


class Gen:
    def __init__(self, op):
        self.op = op
        self.lines = []

    def o(self, s=""):
        self.lines.append(s)

    def loads(self, base, regs):
        """VLD1.P of len(regs) consecutive vectors (<=4 per instruction)."""
        for i in range(0, len(regs), 4):
            grp = regs[i : i + 4]
            lst = ", ".join(f"V{r}.S4" for r in grp)
            self.o(f"\tVLD1.P {16*len(grp)}({base}), [{lst}]")

    def fma(self, x, y, acc):
        if self.op == "dot":
            self.o(f"\tVFMLA V{y}.S4, V{x}.S4, V{acc}.S4")
        else:
            self.o(f"\tVFSUB V{y}.S4, V{x}.S4, V{x}.S4")
            self.o(f"\tVFMLA V{x}.S4, V{x}.S4, V{acc}.S4")

    def blocks(self, nblk, accs):
        xs = list(range(8, 8 + nblk))
        ys = list(range(16, 16 + nblk))
        self.loads("R0", xs)
        self.loads("R1", ys)
        for i in range(nblk):
            self.fma(xs[i], ys[i], accs[i % len(accs)])
        self.o(f"\tSUB ${nblk*W}, R2, R2")

    def zero(self, accs):
        for a in accs:
            self.o(f"\tVMOVI $0, V{a}.B16")

    def opt_stage(self, nblk, accs, nxt):
        self.o(f"\tCMP ${nblk*W}, R2")
        self.o(f"\tBLT {nxt}")
        self.blocks(nblk, accs)
        self.o(f"{nxt}:")

    def masked_stage(self, acc, nxt):
        self.o(f"\tCBZ R2, {nxt}")
        self.o("\tLSL $2, R2, R5")
        self.o("\tMOVD $tailmask4<>(SB), R6")
        self.o("\tADD R5, R6, R6")
        self.o("\tVLD1 (R6), [V24.S4]")
        self.o("\tVLD1 (R3), [V8.S4]")
        self.o("\tVLD1 (R4), [V16.S4]")
        self.o("\tVAND V24.B16, V8.B16, V8.B16")
        self.o("\tVAND V24.B16, V16.B16, V16.B16")
        self.fma(8, 16, acc)
        self.o(f"{nxt}:")

    def fold(self, accs):
        accs = list(accs)
        while len(accs) > 1:
            nxt = []
            for i in range(0, len(accs) - 1, 2):
                self.o(f"\tVFADD V{accs[i+1]}.S4, V{accs[i]}.S4, V{accs[i]}.S4")
                nxt.append(accs[i])
            if len(accs) % 2:
                nxt.append(accs[-1])
            accs = nxt

    def reduce(self):
        self.o("\tVFADDP V0.S4, V0.S4, V0.S4")
        self.o("\tVFADDP V0.S4, V0.S4, V0.S4")
        self.o("\tFMOVS F0, ret+48(FP)")
        self.o("\tRET")

    def kernel(self):
        name = ("dot" if self.op == "dot" else "l2") + "NEON"
        p = name
        self.o(f"// func {name}(x, y []float32) float32")
        self.o("//")
        self.o("// Requires len(x) >= 4 and len(y) >= len(x); see the Go wrapper.")
        self.o("// Go operand order: VFMLA Vm, Vn, Vd computes Vd += Vn*Vm.")
        self.o(f"TEXT ·{name}(SB), NOSPLIT, $0-52")
        self.o("\tMOVD x_base+0(FP), R0")
        self.o("\tMOVD y_base+24(FP), R1")
        self.o("\tMOVD x_len+8(FP), R2")
        self.o("\t// R3/R4: start of the last four elements of x/y, for the masked step.")
        self.o("\tLSL $2, R2, R5")
        self.o("\tADD R5, R0, R3")
        self.o("\tADD R5, R1, R4")
        self.o("\tSUB $16, R3, R3")
        self.o("\tSUB $16, R4, R4")
        self.o(f"\tCMP ${TRIP}, R2")
        self.o(f"\tBLT {p}_s16")
        self.o(f"\t// Main path: {C} chains, {TRIP} elements per trip.")
        self.zero(range(C))
        self.o(f"{p}_loop:")
        xs, ys = list(range(8, 16)), list(range(16, 24))
        self.loads("R0", xs)
        self.loads("R1", ys)
        for i in range(C):
            self.fma(xs[i], ys[i], i)
        self.o(f"\tSUB ${TRIP}, R2, R2")
        self.o(f"\tCMP ${TRIP}, R2")
        self.o(f"\tBGE {p}_loop")
        nb, a, k = C // 2, 0, 0
        while nb >= 1:
            self.opt_stage(nb, list(range(a, a + nb)), f"{p}_t{k}")
            a += nb
            nb //= 2
            k += 1
        self.masked_stage(C - 1, f"{p}_fold")
        self.fold(range(C))
        self.reduce()
        self.o("")
        self.o(f"\t// Short paths for len(x) < {TRIP}: each stage accumulates into as")
        self.o("\t// many chains as it has blocks, so the fold is only as deep as the work.")
        sizes = [16, 8, 4]
        for idx, sz in enumerate(sizes):
            self.o(f"{p}_s{sz}:")
            if idx + 1 < len(sizes):
                self.o(f"\tCMP ${sz}, R2")
                self.o(f"\tBLT {p}_s{sizes[idx+1]}")
            nblk = sz // W
            accs = list(range(nblk))
            self.zero(accs)
            self.blocks(nblk, accs)
            rem, a, k = nblk // 2, 0, 0
            while rem >= 1:
                self.opt_stage(rem, list(range(a, a + rem)), f"{p}_s{sz}_t{k}")
                a += rem
                rem //= 2
                k += 1
            self.masked_stage(nblk - 1, f"{p}_s{sz}_fold")
            self.fold(accs)
            self.reduce()
        return "\n".join(self.lines) + "\n"


if __name__ == "__main__":
    dst = sys.argv[1]
    for op in ("dot", "l2"):
        open(f"{dst}/{op}_neon_arm64.s", "w").write(HEADER + "\n" + Gen(op).kernel())
